test:
account = Account()
account.deposit(5, 10)
try:
    account.withdraw(6, 11)
    raise AssertionError('expected OverdraftError')
except OverdraftError:
    pass
assert account.transactions(0, 10) == [(5, 10)]
for call in (lambda: account.deposit(4, 1), lambda: account.deposit(6, 0), lambda: account.withdraw(6, True), lambda: account.transactions(7, 6)):
    try:
        call()
        raise AssertionError('expected ValueError')
    except ValueError:
        pass
